import{_ as n,o as t,c as e,a1 as i}from"./chunks/framework.DxqwKiYY.js";const r="/pelatihan-webgis-big/assets/image9.BUH0bqsa.png",s="/pelatihan-webgis-big/assets/image18.DuhN_6MW.png",g="/pelatihan-webgis-big/assets/image16.BPy2EmwO.png",o="/pelatihan-webgis-big/assets/image19.CfBhmIlx.png",l="/pelatihan-webgis-big/assets/image22.CS1YJr4K.png",p="/pelatihan-webgis-big/assets/image5.CVMVfij_.png",u="/pelatihan-webgis-big/assets/image1.H9MrHt5v.png",d="/pelatihan-webgis-big/assets/image20.FKRR6yw3.png",m="/pelatihan-webgis-big/assets/image17.qB0xbVTd.png",k="/pelatihan-webgis-big/assets/image14.XkN5YLB0.png",b="/pelatihan-webgis-big/assets/image8.DOp1l4ou.png",h="/pelatihan-webgis-big/assets/image10.Dzi2dj-F.png",c="/pelatihan-webgis-big/assets/image7.edXPnXfF.png",j="/pelatihan-webgis-big/assets/image4.C9SXDBP4.png",f="/pelatihan-webgis-big/assets/image13.BoJoPLV5.png",y="/pelatihan-webgis-big/assets/image2.72rrlH7G.png",w="/pelatihan-webgis-big/assets/image12.C12uJ1Ht.png",B=JSON.parse('{"title":"Persiapan dan Konfigurasi Framework","description":"","frontmatter":{},"headers":[],"relativePath":"Training WebGIS BIG/Modul 1 - Persiapan dan Konfigurasi/Persiapan dan Konfigurasi Framework.md","filePath":"Training WebGIS BIG/Modul 1 - Persiapan dan Konfigurasi/Persiapan dan Konfigurasi Framework.md"}'),_={name:"Training WebGIS BIG/Modul 1 - Persiapan dan Konfigurasi/Persiapan dan Konfigurasi Framework.md"};function P(x,a,G,S,M,K){return t(),e("div",null,[...a[0]||(a[0]=[i('<h1 id="persiapan-dan-konfigurasi-framework" tabindex="-1">Persiapan dan Konfigurasi Framework <a class="header-anchor" href="#persiapan-dan-konfigurasi-framework" aria-label="Permalink to &quot;Persiapan dan Konfigurasi Framework&quot;">​</a></h1><p><strong>Modul 1 - Dasar-Dasar GIS, Konsep WebGIS, Dasar Pemrograman, dan Github</strong></p><h2 id="persiapan-folder-project" tabindex="-1"><strong>Persiapan Folder Project</strong> <a class="header-anchor" href="#persiapan-folder-project" aria-label="Permalink to &quot;**Persiapan Folder Project**&quot;">​</a></h2><ol><li><p>Buat <strong>folder baru</strong> yang akan digunakan sebagai tempat penyimpanan project, kemudian buka <strong>Virtual Studio Code</strong>, lalu <strong>pilih folder</strong> tersebut dengan cara <strong>klik file,</strong> kemudian <strong>klik open folder</strong>, lalu <strong>pilih folder</strong> yang telah dibuat.</p><p><img src="'+r+'" alt=""></p></li><li><p>Selanjutnya setelah memilih folder yang akan menjadi tersebut, berikut ini merupakan halaman awal folder dan project yang akan dirancang dan dibangun.</p><p><img src="'+s+'" alt=""></p></li></ol><h2 id="konfigurasi-framework-next-js" tabindex="-1"><strong>Konfigurasi Framework Next.JS</strong> <a class="header-anchor" href="#konfigurasi-framework-next-js" aria-label="Permalink to &quot;**Konfigurasi Framework Next.JS**&quot;">​</a></h2><ol><li><p>Buka tautan <a href="https://nextjs.org/" target="_blank" rel="noreferrer"><strong>https://nextjs.org/</strong></a> untuk melihat dokumentasi framework yang akan digunakan oleh penguna.</p><p><img src="'+g+'" alt=""></p></li><li><p>Tahapan berikutnya untuk melakukan konfigurasi framework dalam perancangan dan pembangunan WebGIS, maka <strong>buka virtual studio code</strong> kemudian <strong>klik terminal</strong> untuk menjalankan perintah konfigurasi framework.</p><p><img src="'+o+'" alt=""></p></li><li><p>Selanjutnya pada bagian terminal lakukan konfigurasi Next.js dengan menginput perintah berikut ini <strong>npx create-next-app@latest</strong> kemudian <strong>klik enter</strong>. Selanjutnya input nama project yang akan dirancang oleh penggguna.</p><p><img src="'+l+'" alt=""></p></li><li><p>Tahapan berikutnya lakukan konfigurasi next.js pada terminal dengan konfigurasi sebagai berikut.</p><p><img src="'+p+'" alt=""></p></li><li><p>Selanjutnya tunggu hingga proses konfigurasi dan instalasi framework Next.js selesai, berikut merupakan hasil konfigurasi yang telah selesai.</p><p><img src="'+u+'" alt=""></p></li><li><p>Hasil dari konfigurasi framework Next.js pada Virtual Studio Code akan menampilkan folder-folder yang menjadi tempat perancangan dan pembangunan WebGIS.</p><p><img src="'+d+'" alt=""></p></li><li><p>Tahapan berikutnya buka folder yang telah dibuat sebelumnya dengan nama <strong>folder webgis-latihan</strong> dengan cara <strong>klik file</strong>, kemudian <strong>klik open folder</strong>, lalu pilih folder tersebut. Selanjutnya untuk menjalakan web yang telah dikonfigurasi dengan next js dilakukan dengan cara pada <strong>terminal</strong> ketik <strong>npm run dev</strong>.</p><p><img src="'+m+'" alt=""></p></li><li><p>Untuk melihat dan menjalankan web tersebut, buka <strong>browser</strong> yang terdapat dalam perangkat pengguna kemudian masukan url lokal yang terdapat pada <strong>terminal</strong> yaitu <a href="http://localhost:3000/" target="_blank" rel="noreferrer"><strong>http://localhost:3000/</strong></a> maka hasilnya dapat dilihat sebagai berikut.</p><p><img src="'+k+'" alt=""></p></li></ol><h2 id="konfigurasi-project-dengan-repository-github" tabindex="-1"><strong>Konfigurasi Project dengan Repository Github</strong> <a class="header-anchor" href="#konfigurasi-project-dengan-repository-github" aria-label="Permalink to &quot;**Konfigurasi Project dengan Repository Github**&quot;">​</a></h2><ol><li><p>Buka <strong>web github</strong> melalui tautan berikut ini <a href="https://github.com/" target="_blank" rel="noreferrer"><strong>https://github.com/</strong></a> apabila belum memiliki akun maka dapat melakukan registrasi untuk melakukan pembuatan akun github terlebih dahulu.</p><p><img src="'+b+'" alt=""></p></li><li><p>Selanjutnya setelah login pada github, untuk membuat repository baru sebagai tempat penyimpanan project pada github dengan melakukan <strong>klik tombol new</strong>.</p></li><li><p>Selanjutnya pada halaman new, buat halaman baru dengan menginput nama project yang akan dibuat pada github kemudian klik <strong>create repository</strong>.</p><p><img src="'+h+'" alt=""></p></li><li><p>Setelah selesai pembuatan repository barunya selanjutnya untuk melakukan unggah project yang telah dirancang sebelumnya mengikuti perintah yang ada pada github.</p><p><img src="'+c+'" alt=""></p></li><li><p>Selanjutnya untuk mengunggah project yang kita miliki berdasarkan perintah yang sudah ada pada github dilakukan dengan cara <strong>klik kanan</strong> pada folder project, klik <strong>show more option</strong> lalu klik <strong>gitbash</strong>.</p><p><img src="'+j+'" alt=""></p></li><li><p>Pada tampilan gitbash, input perintah-perintah yang telah ada sebelumnya pada poin nomor 4 dengan menyalinnya dari github.</p></li><li><p>Hasil dari project yang telah diunggah pada github maka hasilnya akan menjadi seperti berikut.</p><p><img src="'+f+'" alt=""></p></li></ol><h2 id="cloning-project-github" tabindex="-1"><strong>Cloning Project Github</strong> <a class="header-anchor" href="#cloning-project-github" aria-label="Permalink to &quot;**Cloning Project Github**&quot;">​</a></h2><ol><li><p>Untuk melakukan cloning / menyalin project web yang ada pada github kedalam perangkat peserta, dapat dilakukan dengan mengklik <strong>tombol code</strong> kemudian salin url github project tersebut.</p><p><img src="'+y+'" alt=""></p></li><li><p>Kemudian buka folder yang akan dijadikan tempat penyimpanan, klik kanan, pilih <strong>gitbash</strong>, kemudian pada tampilan gitbash ketik <strong>git clone</strong> lalu <strong>klik kanan</strong> p<strong>aste url project</strong>, lalu <strong>klik enter</strong>.</p></li><li><p>Ketika pertama kali membuka project baru hasil salinan dari github, peserta dapat menjalankan perintah <strong>npm install</strong> pada menu terminal untuk menginstall library yang ada pada project tersebut. Setelah itu peserta dapat menjalankan project tersebut dengan menginput perintah <strong>npm run dev.</strong></p><p><img src="'+w+'" alt=""></p></li></ol><h2 id="mengirim-perubahan-dan-mengambil-hasil-perubahan-web-dengan-git" tabindex="-1"><strong>Mengirim Perubahan dan Mengambil Hasil Perubahan Web dengan Git</strong> <a class="header-anchor" href="#mengirim-perubahan-dan-mengambil-hasil-perubahan-web-dengan-git" aria-label="Permalink to &quot;**Mengirim Perubahan dan Mengambil Hasil Perubahan Web dengan Git**&quot;">​</a></h2><ol><li>Pertama jika project dikerjakan oleh beberapa orang, peserta dapat mengambil perubahan tersebut dengan menginput perintah git pull pada menu terminal serta tunggu hingga selesai.</li><li>Kedua jika peserta ingin mengirim perubahan hasil web yang telah dibuat peserta dapat menginput perintah pada github pertama <strong>git add .</strong> kemudian klik enter, lanjutkan perintah kedua yaitu input git commit -m “ isi komentar ” dan tambahkan komentar sebagai informasi perubahan yang telah dibuat lalu klik enter, kemudian tahap terakhir input perintah git push maka hasil perubahan yang telah dibuat oleh peserta akan masuk kedalam project github.</li></ol><h2 id="penjelasan-perintah-dasar-next-js-npm-git-dan-github" tabindex="-1"><strong>Penjelasan Perintah Dasar Next.js, NPM, Git, dan GitHub</strong> <a class="header-anchor" href="#penjelasan-perintah-dasar-next-js-npm-git-dan-github" aria-label="Permalink to &quot;**Penjelasan Perintah Dasar Next.js, NPM, Git, dan GitHub**&quot;">​</a></h2><table tabindex="0"><thead><tr><th>npx create-next-app@latest</th><th>Membuat kerangka awal project menggunakan Next.js.</th></tr></thead><tbody><tr><td>npm install</td><td>Menginstall library atau package yang dibutuhkan project.</td></tr><tr><td>npm run dev</td><td>Menjalankan project untuk proses pengembangan.</td></tr><tr><td>npm run build</td><td>Build project</td></tr><tr><td>npm run start</td><td>Menjalankan hasil build project.</td></tr><tr><td>git init</td><td>Menginisialisasi Git pada project.</td></tr><tr><td>git add .</td><td></td></tr><tr><td>git commit -m &quot;isi komentar&quot;</td><td>Menyimpan perubahan project ke dalam Git.</td></tr><tr><td>git remote add origin <a href="https://github.com/username/project.git" target="_blank" rel="noreferrer">https://github.com/username/project.git</a></td><td>Menghubungkan project lokal dengan repository GitHub.</td></tr><tr><td>git push</td><td>Mengirim project/commit dari komputer lokal ke GitHub.</td></tr><tr><td>git pull</td><td>Mengambil hasil perubahan pengembangan web yang telah dibuat.</td></tr></tbody></table>',14)])])}const F=n(_,[["render",P]]);export{B as __pageData,F as default};
